INSERT INTO `wp_options` VALUES (14291,'_transient_dlm_extension_json','{\"message\":\"\",\"extensions\":[{\"name\":\"Contact Form 7\",\"desc\":\"<p>Take control of your digital content distribution with the Contact Form 7 integration for Download Monitor. It\\u2019s simple, effective, and gives you the tools to manage your downloads like a pro! \\u00a0<\\/p>\",\"product_id\":\"dlm-cf7-lock\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/contact-form-7\\/\",\"price\":0,\"sale_price\":0,\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2024\\/08\\/DLM-CF7-extension.png\"},{\"name\":\"WPForms\",\"desc\":\"<p>With WPForms and Download Monitor, managing access to your digital content has never been easier or more efficient.<\\/p>\",\"product_id\":\"dlm-wpforms-lock\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/wpforms\\/\",\"price\":0,\"sale_price\":0,\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2024\\/08\\/DLM-WPForms-extension.png\"},{\"name\":\"Enhanced Metrics\",\"desc\":\"Use it to get access to advanced download metrics, such as downloads by user role or downloads by status (redirected, completed, failed, etc).\",\"product_id\":\"dlm-enhanced-metrics\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/enhanced-metrics\\/\",\"price\":\"\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2022\\/10\\/enhanced-analytics@2x.png\"},{\"name\":\"Buttons\",\"desc\":\"<p>Create beautiful, fully customizable download buttons with our Buttons extension. No coding or file editing required!<\\/p>\",\"product_id\":\"dlm-buttons\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/buttons\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2018\\/09\\/icon-buttons.png\"},{\"name\":\"Captcha\",\"desc\":\"The Captcha extension for Download Monitor allows you to require users to complete a Google reCAPTCHA before they gain access to a download.\",\"product_id\":\"dlm-captcha\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/captcha\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2017\\/08\\/dlm-captcha.png\"},{\"name\":\"Downloading Page\",\"desc\":\"<p>The Downloading Page extension for Download Monitor forces your downloads to be served from a separate page.<\\/p>\",\"product_id\":\"dlm-downloading-page\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/downloading-page\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2016\\/08\\/dlm-downloading-page.png\"},{\"name\":\"Google Drive\",\"desc\":\"<p>Lets you use the files hosted on your Google Drive as Download Monitor files.<\\/p>\",\"product_id\":\"dlm-google-drive\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/google-drive\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2016\\/03\\/dlm-google-drive.jpg\"},{\"name\":\"Terms and Conditions\",\"desc\":\"Require your users to accept your terms and conditions before they can download your files.\",\"product_id\":\"dlm-terms-and-conditions\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/terms-conditions\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2016\\/03\\/dlm-terms-and-conditions.png\"},{\"name\":\"Twitter Lock\",\"desc\":\"The Twitter Lock extension for Download Monitor allows you to require users to tweet your pre-defined text before they gain access to a download.\",\"product_id\":\"dlm-twitter-lock\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/twitter-lock\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/11\\/twitter-lock.jpg\"},{\"name\":\"Advanced Access Manager\",\"desc\":\"<p>The Advanced Access Manager extension allows you to create advanced download limitations per download and on a global level.<\\/p>\",\"product_id\":\"dlm-advanced-access-manager\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/advanced-access-manager\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/07\\/dlm-advanced-access-manager.jpg\"},{\"name\":\"Email Notification\",\"desc\":\"The Email Notification extension for Download Monitor sends you an email whenever one of your files is downloaded.\",\"product_id\":\"dlm-email-notification\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/email-notification\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/05\\/dlm-email-notification.jpg\"},{\"name\":\"CSV Exporter\",\"desc\":\"Export all your downloads including categories, tags and file versions to a CSV file with a single click!\",\"product_id\":\"dlm-csv-exporter\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/csv-exporter\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/02\\/dlm-csv-exporter.jpg\"},{\"name\":\"MailChimp Lock\",\"desc\":\"<p>The MailChimp Lock for Download Monitor allows you to require users to be subscribed to your MailChimp list before they gain access to a download.<\\/p>\",\"product_id\":\"dlm-mailchimp-lock\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/mailchimp-lock\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/02\\/dlm-mailchimp-lock.jpg\"},{\"name\":\"CSV Importer\",\"desc\":\"<p>Mass import up to thousands of Downloads into Download Monitor with the CSV Importer.<\\/p>\",\"product_id\":\"dlm-csv-importer\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/csv-importer\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/02\\/dlm-csv-importer.jpg\"},{\"name\":\"Gravity Forms\",\"desc\":\"<p>The Gravity Forms extension for Download Monitor allows you to require users to fill out a Gravity Forms form before they gain access to a download.<\\/p>\",\"product_id\":\"dlm-gravity-forms\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/gravity-forms\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/01\\/dlm-gravity-forms.jpg\"},{\"name\":\"Ninja Forms\",\"desc\":\"<p>The Ninja Forms extension for Download Monitor allows you to require users to fill in a Ninja Forms form before they gain access to a download.<\\/p>\",\"product_id\":\"dlm-ninja-forms\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/ninja-forms\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/01\\/dlm-ninja-forms.jpg\"},{\"name\":\"Email Lock\",\"desc\":\"<p>The Email Lock extension for Download Monitor allows you to require users to fill in their email address before they gain access to a download.<\\/p>\",\"product_id\":\"dlm-email-lock\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/email-lock\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/01\\/email-lock.jpg\"},{\"name\":\"DLM Legacy Importer\",\"desc\":\"Converts downloads from the legacy 3.0.x versions to the new Download Monitor format (which uses post types). Go to Tools &gt; Import to get importing.\",\"product_id\":\"dlm-legacy-importer\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/dlm-legacy-importer\\/\",\"price\":\"0\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/01\\/legacy-importer.jpg\"},{\"name\":\"Amazon S3\",\"desc\":\"Link to files hosted on Amazon s3 so that you can serve secure, expiring download links.\",\"product_id\":\"dlm-amazon-s3\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/amazon-s3\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/01\\/amazons3.jpg\"},{\"name\":\"Page Addon\",\"desc\":\"<p>Add a self contained [download_page] shortcode to your site to list downloads, categories, tags, and show info pages about each of your resources.<\\/p>\",\"product_id\":\"dlm-page-addon\",\"url\":\"https:\\/\\/download-monitor.com\\/extensions\\/page-addon\\/\",\"price\":\"39\",\"sale_price\":\"\",\"image\":\"https:\\/\\/download-monitor.com\\/wp-content\\/uploads\\/2015\\/01\\/page-addon.jpg\"},{\"name\":\"LearnDash Integration\",\"desc\":\"With Download Monitor & LearnDash integration you can allow only certain LearnDash groups users to download from your website.\",\"slug\":\"dlm-aam-learndash.php\",\"dir\":\"download-monitor-learndash-integration\",\"free_extension\":true,\"url\":\"\",\"price\":\"\",\"sale_price\":\"\",\"image\":\"\"},{\"name\":\"Restrict Content Integration\",\"desc\":\"Allow only certain Restrict Content groups users to download from your website and set a maximum number of downloads based on their subscription duration.\",\"slug\":\"dlm-aam-restrict-content-pro.php\",\"dir\":\"download-monitor-restrict-content-integration\",\"free_extension\":true,\"url\":\"\",\"price\":\"\",\"sale_price\":\"\",\"image\":\"\"},{\"name\":\"Paid Memberships Pro Integration\",\"desc\":\"Allow only certain Paid Membership Pro groups users to download from your website and set a maximum number of downloads based on their subscription duration.\",\"slug\":\"dlm-aam-paid-membership-pro.php\",\"dir\":\"download-monitor-paid-membership-pro-integration\",\"free_extension\":true,\"url\":\"\",\"price\":\"\",\"sale_price\":\"\",\"image\":\"\"},{\"name\":\"CORS\",\"desc\":\"Adds the possibility for Download Monitor\\u2019s XHR requests to be processed from other domains.\",\"slug\":\"dlm-cors.php\",\"dir\":\"download-monitor-cors\",\"free_extension\":true,\"url\":\"\",\"price\":\"\",\"sale_price\":\"\",\"image\":\"\"},{\"name\":\"Migrate Download Counts\",\"desc\":\"Migrate DLM download counts. Used for migrating from DLM 4.5.x and below to DLM 4.6.0 and above.\",\"slug\":\"dlm-migrate-download-counts.php\",\"dir\":\"download-monitor-migrate-download-counts\",\"free_extension\":true,\"url\":\"\",\"price\":\"\",\"sale_price\":\"\",\"image\":\"\"}]}','off');
