INSERT INTO `wp_posts` VALUES (228,1,'2024-09-26 22:13:48','2024-09-26 22:13:48','[products]		\n<form name=\"checkout\" method=\"post\" action=\"http://safety.local/checkout/\" enctype=\"multipart/form-data\">\n			<!--open container-->\n				<!--open column-1-->\n        				<wc-order-attribution-inputs></wc-order-attribution-inputs>\n		<h3>Billing Details</h3>\n		<p id=\"billing_email_field\" data-priority=\"110\"><label for=\"billing_email\">Email Address&nbsp;<abbr title=\"required\">*</abbr></label><input type=\"email\" name=\"billing_email\" id=\"billing_email\" placeholder=\"Email Address\"  value=\"dev-email@wpengine.local\" aria-required=\"true\" autocomplete=\"email username\" /></p>	\n			<h3></h3>\n							<p id=\"order_comments_field\" data-priority=\"\"><label for=\"order_comments\">Order notes&nbsp;(optional)</label><textarea name=\"order_comments\" id=\"order_comments\" placeholder=\"Notes about your order, e.g. special notes for delivery.\"  rows=\"2\" cols=\"5\"></textarea></p>					\n        							<!--close column-1-->\n					<!--open column-2-->\n							<!--open column-inner-->\n								<!--open order_review-->\n            	<h3 id=\"order_review_heading\">Your order</h3>\n            		<table>\n	<thead>\n		<tr>\n			<th>Product</th>\n			<th>Total</th>\n		</tr>\n	</thead>\n	<tbody>\n							<tr>\n						<td>\n                                <a href=\"http://safety.local/cart/?remove_item=e2c0be24560d78c5e599c2a9c9d0bbd2&#038;_wpnonce=6630ba091a\" aria-label=\"Remove this item\" data-product_id=\"203\" data-product_sku=\"\" data-balloon-pos=\"up\" data-balloon=\"Remove\">&times;</a>                                \n                                    <a href=\"http://safety.local/product/product-1/\"><img width=\"300\" height=\"300\" src=\"http://safety.local/wp-content/uploads/woocommerce-placeholder-300x300.png\" alt=\"Placeholder\" decoding=\"async\" srcset=\"http://safety.local/wp-content/uploads/woocommerce-placeholder-300x300.png 300w, http://safety.local/wp-content/uploads/woocommerce-placeholder-100x100.png 100w, http://safety.local/wp-content/uploads/woocommerce-placeholder-600x600.png 600w, http://safety.local/wp-content/uploads/woocommerce-placeholder-1024x1024.png 1024w, http://safety.local/wp-content/uploads/woocommerce-placeholder-150x150.png 150w, http://safety.local/wp-content/uploads/woocommerce-placeholder-768x768.png 768w, http://safety.local/wp-content/uploads/woocommerce-placeholder-624x624.png 624w, http://safety.local/wp-content/uploads/woocommerce-placeholder.png 1200w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></a>                                \n    							     <a href=\"http://safety.local/product/product-1/\">Product 1</a>&nbsp;\n    							     Qty: <strong>23</strong>\n						</td>\n						<td>\n						<bdi>&#36;0.00</bdi>						</td>\n					</tr>\n										<tr>\n						<td>\n                                <a href=\"http://safety.local/cart/?remove_item=7eabe3a1649ffa2b3ff8c02ebfd5659f&#038;_wpnonce=6630ba091a\" aria-label=\"Remove this item\" data-product_id=\"206\" data-product_sku=\"\" data-balloon-pos=\"up\" data-balloon=\"Remove\">&times;</a>                                \n                                    <a href=\"http://safety.local/product/product-2/\"><img width=\"300\" height=\"300\" src=\"http://safety.local/wp-content/uploads/woocommerce-placeholder-300x300.png\" alt=\"Placeholder\" decoding=\"async\" srcset=\"http://safety.local/wp-content/uploads/woocommerce-placeholder-300x300.png 300w, http://safety.local/wp-content/uploads/woocommerce-placeholder-100x100.png 100w, http://safety.local/wp-content/uploads/woocommerce-placeholder-600x600.png 600w, http://safety.local/wp-content/uploads/woocommerce-placeholder-1024x1024.png 1024w, http://safety.local/wp-content/uploads/woocommerce-placeholder-150x150.png 150w, http://safety.local/wp-content/uploads/woocommerce-placeholder-768x768.png 768w, http://safety.local/wp-content/uploads/woocommerce-placeholder-624x624.png 624w, http://safety.local/wp-content/uploads/woocommerce-placeholder.png 1200w\" sizes=\"(max-width: 300px) 100vw, 300px\" /></a>                                \n    							     <a href=\"http://safety.local/product/product-2/\">Product 2</a>&nbsp;\n    							     Qty: <strong>5</strong>\n						</td>\n						<td>\n						<bdi>&#36;0.00</bdi>						</td>\n					</tr>\n						</tbody>\n	<tfoot>\n		<tr>\n			<th>Subtotal</th>\n			<td><bdi>&#36;0.00</bdi></td>\n		</tr>\n		<tr>\n			<th>Total</th>\n			<td><strong><bdi>&#36;0.00</bdi></strong> </td>\n		</tr>\n	</tfoot>\n</table>\n									<!--close wc_order_review-->\n								<!--close order_review-->\n								<!--reopen wc_order_review-2-->\n		<noscript>\n			Since your browser does not support JavaScript, or it is disabled, please ensure you click the <em>Update Totals</em> button before placing your order. You may be charged more than the amount stated above if you fail to do so.			<br/><button type=\"submit\" name=\"woocommerce_checkout_update_totals\" value=\"Update totals\">Update totals</button>\n		</noscript>\n		<p>Your personal data will be used to process your order, support your experience throughout this website, and for other purposes described in our <a href=\"http://safety.local/?page_id=3\" target=\"_blank\" rel=\"noopener\">privacy policy</a>.</p>\n		<button type=\"submit\" name=\"woocommerce_checkout_place_order\" id=\"place_order\" value=\"Place order\" data-value=\"Place order\">Place order</button>\n		<input type=\"hidden\" id=\"woocommerce-process-checkout-nonce\" name=\"woocommerce-process-checkout-nonce\" value=\"b2643a799a\" /><input type=\"hidden\" name=\"_wp_http_referer\" value=\"/wp-admin/admin-ajax.php\" />	\n            											<!--close wc_order_review-2-->\n						<!--close column-inner-->\n					<!--close column-2-->\n				<!--close container-->\n</form>','Elementor Products Archive #228','','publish','closed','closed','','elementor-products-archive-228','','','2024-10-04 01:08:29','2024-10-04 01:08: