INSERT INTO `wp_posts` VALUES (268,1,'2024-10-03 19:18:15','2024-10-03 19:18:15','<form name=\"checkout\" method=\"post\" action=\"http://safety.local/checkout/\" enctype=\"multipart/form-data\">\n			<!--open container-->\n				<!--open column-1-->\n        				<wc-order-attribution-inputs></wc-order-attribution-inputs>\n		<h3>Billing Details</h3>\n		<p id=\"billing_first_name_field\" data-priority=\"10\"><label for=\"billing_first_name\">First Name&nbsp;<abbr title=\"required\">*</abbr></label><input type=\"text\" name=\"billing_first_name\" id=\"billing_first_name\" placeholder=\"First Name\"  value=\"\" aria-required=\"true\" autocomplete=\"given-name\" /></p><p id=\"billing_last_name_field\" data-priority=\"20\"><label for=\"billing_last_name\">Last Name&nbsp;<abbr title=\"required\">*</abbr></label><input type=\"text\" name=\"billing_last_name\" id=\"billing_last_name\" placeholder=\"Last Name\"  value=\"\" aria-required=\"true\" autocomplete=\"family-name\" /></p><p id=\"billing_company_field\" data-priority=\"30\"><label for=\"billing_company\">Company Name&nbsp;(optional)</label><input type=\"text\" name=\"billing_company\" id=\"billing_company\" placeholder=\"Company Name\"  value=\"\" autocomplete=\"organization\" /></p><p id=\"billing_country_field\" data-priority=\"40\"><label for=\"billing_country\">Country / Region&nbsp;<abbr title=\"required\">*</abbr></label><select name=\"billing_country\" id=\"billing_country\" aria-required=\"true\" autocomplete=\"country\" data-placeholder=\"Select a country / region&hellip;\" data-label=\"Country / Region\"><option value=\"\">Select a country / region&hellip;</option><option value=\"AF\" >Afghanistan</option><option value=\"AX\" >Åland Islands</option><option value=\"AL\" >Albania</option><option value=\"DZ\" >Algeria</option><option value=\"AS\" >American Samoa</option><option value=\"AD\" >Andorra</option><option value=\"AO\" >Angola</option><option value=\"AI\" >Anguilla</option><option value=\"AQ\" >Antarctic